// A distinct entry point lets older installed workers update without clearing data.
(async()=>{if(!('serviceWorker'in navigator)){location.replace('/');return;}const status=document.getElementById('status'),detail=document.getElementById('detail');let registration,timer,poll,finished=false;function stop(){clearTimeout(timer);clearTimeout(poll);}function fail(){if(finished)return;finished=true;stop();status.textContent='Şu anda bağlantı kurulamadı.';detail.textContent='İnternet bağlantın geldiğinde yeniden dene. Planların ve notların bu cihazda korunur.';document.getElementById('retry').hidden=false;}
function identify(worker){if(!worker)return Promise.resolve(false);return new Promise(resolve=>{const channel=new MessageChannel(),timeout=setTimeout(()=>{channel.port1.close();resolve(false);},500);channel.port1.onmessage=event=>{clearTimeout(timeout);channel.port1.close();resolve(event.data?.type==='APP_VERSION'&&event.data.version==='gun-payi-v4.1.1');};worker.postMessage({type:'APP_VERSION'},[channel.port2]);});}
async function check(){if(finished)return;try{if(await identify(registration?.active)){finished=true;stop();location.replace('/');return;}registration?.waiting?.postMessage({type:'ACTIVATE_UPDATE'});}catch{}if(!finished)poll=setTimeout(check,600);}
try{timer=setTimeout(fail,15000);registration=await navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'});void registration.update().catch(()=>{});void check();}catch{fail();}})();
